import { Group, Mesh, PlaneGeometry, CylinderGeometry, MeshStandardNodeMaterial, MeshBasicNodeMaterial, Vector3, Color } from 'three/webgpu';
import { uv, mix, length, smoothstep, vec2, vec3 } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const group = new Group();

  // ---------- Backdrop Gradient Plane ----------
  const gradientStops = (config.intent?.visualSpec?.colors?.gradientStops) || [
    { at: 0, hex: '#0b0b10' },
    { at: 1, hex: '#16161d' },
  ];
  const startColor = new Color(gradientStops[0].hex);
  const endColor = new Color(gradientStops[gradientStops.length - 1].hex);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(vec3(startColor.r, startColor.g, startColor.b), vec3(endColor.r, endColor.g, endColor.b), uv().y);
  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // ---------- Plinth ----------
  const plinthMat = new MeshStandardNodeMaterial({
    color: new Color('#14141a'),
    roughness: 0.7,
    metalness: 0.3,
  });
  const plinth = new Mesh(new CylinderGeometry(1.4, 1.4, 0.25, 32), plinthMat);
  plinth.position.set(0, -1.225, 0);
  group.add(plinth);

  // ---------- Contact Shadow ----------
  const shadowMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const uvNode = uv();
  const dist = length(sub(uvNode.xy, vec2(0.5, 0.5)));
  const opacityNode = mul(smoothstep(0.5, 0.0, dist), 0.55);
  shadowMat.opacityNode = opacityNode;
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  const shadow = new Mesh(new PlaneGeometry(3.2, 3.2), shadowMat);
  shadow.rotation.x = -Math.PI / 2;
  shadow.position.set(0, -1.35, 0);
  group.add(shadow);

  // ---------- Load Watch Mesh ----------
  let gltf = null;
  ctx.glbLoader.loadGLB(config.meshUrl).then((g) => {
    gltf = g;
    if (gltf.scene) {
      group.add(gltf.scene);
    }
  });

  // ---------- Text Content ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textGroup = new Group();
  for (const item of items) {
    const opts = {
      fontSize: item.typography?.fontSize ?? 68,
      color: config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
      align: 'left',
    };
    const txtObj = ctx.fontAtlas.createText(item.text, opts);
    // Position based on role
    let yPos = 0;
    if (item.role === 'headline') yPos = -1.5;
    else if (item.role === 'body') yPos = -1.8;
    else if (item.role === 'caption') yPos = -2.0;
    txtObj.position.set(0, yPos, 0);
    textGroup.add(txtObj);
  }
  group.add(textGroup);

  // ---------- Cinematic Primitives ----------
  const activePrimitives = [];

  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      const name = prim.name;
      const params = prim.params || {};
      const trigger = prim.trigger;
      // Apply immediately; primitives handle their own triggers internally
      const instance = ctx.primitives[name](group, params);
      activePrimitives.push(instance);
    }
  }

  // ---------- UserData & Cleanup ----------
  group.userData.handlers = {};
  group.userData.cleanup = () => {
    // Dispose GLTF resources
    if (gltf && gltf.scene) {
      gltf.scene.traverse((obj) => {
        if (obj.isMesh) {
          if (obj.geometry) obj.geometry.dispose();
          if (obj.material) {
            if (Array.isArray(obj.material)) {
              obj.material.forEach((m) => m.dispose());
            } else {
              obj.material.dispose();
            }
          }
        }
      });
    }
    // Dispose materials
    backdropMat.dispose();
    plinthMat.dispose();
    shadowMat.dispose();
    // Cleanup primitives
    for (const p of activePrimitives) {
      if (p && typeof p.cleanup === 'function') p.cleanup();
    }
    // Kill any GSAP timelines (none created here but safe)
    gsap.globalTimeline.clear();
  };

  return group;
}
